def solve(grid):
    R=len(grid); C=len(grid[0])
    cells={(r,c) for r in range(R) for c in range(C) if grid[r][c]==8}
    pieces=[]
    for r in range(R-1):
      for c in range(C-1):
        sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
        if sq<=cells: pieces.append((1,sq))
        for miss,color in [((0,0),2),((1,0),3),((0,1),4)]:
          s={(r+dr,c+dc) for dr in (0,1) for dc in (0,1) if (dr,dc)!=miss}
          if s<=cells: pieces.append((color,s))
    by={p:[] for p in cells}
    for i,(_,s) in enumerate(pieces):
      for p in s: by[p].append(i)
    sols=[]
    def rec(rem,ch):
      if not rem:
       sols.append(ch); return
      p=min(rem,key=lambda p:sum(pieces[i][1]<=rem for i in by[p]))
      for i in by[p]:
       col,s=pieces[i]
       if s<=rem: rec(rem-s,ch+[(col,s)])
    rec(cells,[])
    if not sols:return None
    out=[[0]*C for _ in range(R)]
    for col,s in sols[0]:
      for r,c in s:out[r][c]=col
    return out, len(sols)
