program='''def transform(grid):
    rows, cols = len(grid), len(grid[0])
    cells = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 8}
    pieces = []
    # The shape consists of 2x2 squares and L triominoes. The output
    # color marks the square or the L's missing corner.
    for r in range(rows - 1):
        for c in range(cols - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if square <= cells:
                pieces.append((1, square))
            for missing, color in [((0, 0), 2), ((1, 0), 3), ((0, 1), 4)]:
                triomino = {
                    (r + dr, c + dc)
                    for dr in (0, 1) for dc in (0, 1)
                    if (dr, dc) != missing
                }
                if triomino <= cells:
                    pieces.append((color, triomino))

    by_cell = {cell: [] for cell in cells}
    for i, (_, piece) in enumerate(pieces):
        for cell in piece:
            by_cell[cell].append(i)

    solution = None
    def search(remaining, chosen):
        nonlocal solution
        if not remaining:
            solution = chosen
            return True
        cell = min(remaining, key=lambda p: sum(pieces[i][1] <= remaining for i in by_cell[p]))
        for i in by_cell[cell]:
            color, piece = pieces[i]
            if piece <= remaining and search(remaining - piece, chosen + [(color, piece)]):
                return True
        return False

    if not search(cells, []):
        raise ValueError("No valid square/L-triomino tiling found")
    result = [[0] * cols for _ in range(rows)]
    for color, piece in solution:
        for r, c in piece:
            result[r][c] = color
    return result
'''
